import numpy as np
rng=np.random.default_rng(1)
def sig(x): return 1.0/(1.0+np.exp(-np.clip(x,-500,500)))
def qreq(cost,sl,sr,cmax,qmax,qmin):
    nc=np.clip(cost/cmax,0,10);qr=qmax-qmin;left=nc<0.5
    ql=qmin+(qr/2)*sig(sl*(nc-0.25)*10);qh=qmin+(qr/2)+(qr/2)*sig(sr*(nc-0.75)*10)
    return np.where(cost>cmax,qmax,np.where(left,ql,qh))
BASE=0.20;TM={'A':0.75,'B':0.90,'C':0.75};PR={'A':14,'B':55,'C':99};QU={'A':200,'B':400,'C':2000}
def convS1(qshared,gb,promo,n=120000):
    qmin=np.maximum(1e-4,rng.normal(0.10,0.05,n));qr=np.maximum(1e-4,rng.normal(0.45,0.09,n));qmax=qmin+qr
    cmax=np.maximum(15,rng.normal(50,20*1.2,n));sl=np.clip(rng.exponential(1,n)+0.2,0.2,6);sr=np.clip(rng.exponential(2,n)+0.8,0.5,7)
    usage=np.maximum(1,rng.normal(80,40,n));base=BASE+qshared+gb;noise=rng.uniform(0.8,1.1,n)
    bp=np.zeros(n);bs=np.full(n,-np.inf);pi={'A':1,'B':2,'C':3}
    for p in ['A','B','C']:
        ep=max(0,PR[p]-promo);qf=np.minimum(1,QU[p]/usage);ql=base*TM[p]*qf*noise
        sat=ql-qreq(np.full(n,ep),sl,sr,cmax,qmax,qmin);b=(sat>bs)&(sat>0)&(ep<=cmax)
        bs=np.where(b,sat,bs);bp=np.where(b,pi[p],bp)
    return np.mean(bp>0),{p:np.mean(bp==pi[p]) for p in ['A','B','C']}
print('S1 conversion vs lead promo (qshared=0.067,gS1=0.0817):')
